import{evaluateSourceOperation}from'../ops/source-governance-paid-use.js';const uniq=v=>[...new Set((v??[]).filter(Boolean))];
export function buildEvidenceLinkedReport(input){if(!input?.reportId||!input?.title)throw new TypeError('reportId and title required');const sections=(input.sections??[]).map(s=>{if(!s?.id||!s?.title)throw new TypeError('section id/title required');if(!Array.isArray(s.evidenceRefs)||!s.evidenceRefs.length)throw new Error(`section ${s.id} has no evidence`);return Object.freeze({id:s.id,title:s.title,summary:s.summary??'',evidenceRefs:uniq(s.evidenceRefs)})});if(!sections.length)throw new Error('at least one evidence-linked section required');return Object.freeze({schemaVersion:'earthus.report.v1',reportId:input.reportId,title:input.title,generatedAt:input.generatedAt??new Date().toISOString(),subject:input.subject??null,sections,sourceRefs:uniq(sections.flatMap(s=>s.evidenceRefs).map(r=>input.evidenceIndex?.[r]?.sourceRef)),disclaimerClass:input.disclaimerClass??'EVIDENCE_BASED_ANALYSIS'})}
export function authorizeReportDelivery({report,sources,mode='VIEW',quotaRemaining=1}){if(!report)throw new TypeError('report required');if(quotaRemaining<=0)return Object.freeze({state:'BLOCKED',reason:'QUOTA_EXHAUSTED'});const operation=mode==='API'?'apiResale':mode==='EXPORT'?'export':'display';for(const source of sources??[]){const v=evaluateSourceOperation(source,operation,{derivedOnly:mode!=='VIEW'});if(v.state!=='ALLOWED')return Object.freeze({state:'BLOCKED',reason:v.reason,sourceRef:source.sourceRef})}return Object.freeze({state:'ALLOWED',operation,reportId:report.reportId})}
